// =============================================================================
// fx_cabsim.sv - SIMULACION DE GABINETE por convolucion (cab sim).
//
// Convoluciona la senal con la respuesta al impulso (IR) de un parlante de
// guitarra de 12" en gabinete cerrado: FIR de 256 taps, Q1.31.
//
// POR QUE IMPORTA: una distorsion cruda a auriculares suena "avispa digital"
// porque en la vida real SIEMPRE pasa por un parlante, que corta todo arriba
// de ~4-5kHz y tiene resonancias propias. Sin eso, el oido no la reconoce
// como "distorsion de guitarra". Este bloque es el que la hace sonar a disco.
//
// Respuesta modelada:
//   -18 dB/oct por debajo de 85 Hz   | resonancia del cono +3.5dB @115Hz
//   presencia +4dB @2.5kHz           | caida 30 dB/oct arriba de 4.2kHz
//
// Costo: 256 ciclos por muestra (de los 1041 disponibles a 50MHz/48kHz).
// Va AL FINAL de la cadena (despues de todos los efectos).
// =============================================================================
module fx_cabsim (
  input  logic               clk,
  input  logic               rst_n,
  input  logic               enable,
  input  logic               in_valid,
  output logic               in_ready,
  input  logic signed [31:0] in_data,
  output logic               out_valid,
  input  logic               out_ready,
  output logic signed [31:0] out_data
);
  localparam int NTAPS = 256;
  localparam logic [32*NTAPS-1:0] IR = 8192';

  logic f_iv, f_ir, f_ov, f_or;
  logic signed [31:0] f_od;

  logic enable_d, st_clear;
  always_ff @(posedge clk) begin
    if (!rst_n) begin enable_d <= 1'b0; st_clear <= 1'b0; end
    else begin enable_d <= enable; st_clear <= enable && !enable_d; end
  end

  fir_serial #(.N(NTAPS), .COEFS(IR)) u_fir (
    .clk(clk), .rst_n(rst_n), .state_clear(st_clear),
    .in_valid(f_iv), .in_ready(f_ir), .in_data(in_data),
    .out_valid(f_ov), .out_ready(f_or), .out_data(f_od)
  );

  // bypass estandar: un solo driver por senal
  assign f_iv      = enable && in_valid;
  assign f_or      = enable && out_ready;
  assign in_ready  = enable ? f_ir : out_ready;
  assign out_valid = enable ? f_ov : in_valid;
  assign out_data  = enable ? f_od : in_data;
endmodule
